const body = $input.item.json.body || $input.item.json;

// Ignora mensagens de status ou do proprio bot
if (!body.data || body.data.key.fromMe || !body.data.message) {
  return [];
}

const remoteJid = body.data.key.remoteJid;
if (remoteJid.includes('@g.us')) {
  return [];
}

const pushName = body.data.pushName || 'Cliente';
let text = '';
if (body.data.message.conversation) {
  text = body.data.message.conversation;
} else if (body.data.message.extendedTextMessage && body.data.message.extendedTextMessage.text) {
  text = body.data.message.extendedTextMessage.text;
}

text = text.trim();
const cleanText = text.toLowerCase();

return [{
  json: {
    remoteJid: remoteJid,
    number: remoteJid.replace('@s.whatsapp.net', ''),
    pushName: pushName,
    text: text,
    cleanText: cleanText
  }
}];

const inputData = $('Filtrar & Tratar Mensagem').item.json;
let rawSession = null;

if ($input.item && $input.item.json && $input.item.json.session_data) {
  rawSession = $input.item.json.session_data;
}

let session = { state: 'MAIN_MENU', context: {}, attempts: 0 };
if (rawSession) {
  try {
    session = typeof rawSession === 'string' ? JSON.parse(rawSession) : rawSession;
    if (typeof session.attempts !== 'number') session.attempts = 0;
  } catch (e) {
    session = { state: 'MAIN_MENU', context: {}, attempts: 0 };
  }
}

const input = inputData.cleanText;
let responseText = '';
let nextState = session.state;
let sessionData = session.context || {};
let attempts = session.attempts || 0;

// Comando global para reiniciar
if (input === 'menu' || input === 'inicio' || input === 'sair' || input === 'cancelar') {
  session.state = 'MAIN_MENU';
  sessionData = {};
  attempts = 0;
}

function handleInvalidInput(repeatQuestion) {
  attempts++;
  if (attempts >= 3) {
    nextState = 'MAIN_MENU';
    sessionData = {};
    attempts = 0;
    return '⚠️ *Parece que estamos com dificuldades para entender sua resposta.*\n\nO que deseja fazer?\n\nDigite *MENU* para reiniciar o atendimento ou aguarde para falar com um de nossos atendentes.';
  }
  return '⚠️ *Não entendi sua resposta.* (Tentativa ' + attempts + '/3)\n\n' + repeatQuestion;
}

switch (session.state) {
  case 'MAIN_MENU':
    attempts = 0;
    if (input === '1') {
      nextState = 'SUPORTE_LOS';
      responseText = '🔧 *Suporte Técnico*\n\nVamos verificar sua conexão! Por favor, observe as luzes do seu modem/roteador:\n\nA luz com o nome *LOS* (ou PON) está *vermelha* ou *piscando*?\n\n1️⃣ *Sim*\n2️⃣ *Não*';
    } else if (input === '2') {
      nextState = 'FINANCEIRO_MENU';
      responseText = '💰 *Atendimento Financeiro*\n\nPor favor, escolha uma opção:\n\n1️⃣ *Segunda via de boleto / Código PIX*\n2️⃣ *Consultar faturas em aberto*\n3️⃣ *Falar com atendente financeiro*\n\n_(Digite *MENU* para voltar)_';
    } else if (input === '3') {
      nextState = 'COMERCIAL_MENU';
      responseText = '🛒 *Comercial & Planos*\n\nPor favor, escolha uma opção:\n\n1️⃣ *Conhecer planos de Fibra*\n2️⃣ *Upgrade de velocidade*\n3️⃣ *Falar com consultor de vendas*\n\n_(Digite *MENU* para voltar)_';
    } else {
      responseText = 'Olá, *' + inputData.pushName + '*! 👋 Seja bem-vindo ao atendimento do seu Provedor de Internet.\n\nPor favor, digite o número da opção desejada:\n\n1️⃣ *Suporte Técnico*\n2️⃣ *Financeiro & 2ª Via*\n3️⃣ *Comercial & Planos*';
    }
    break;

  case 'SUPORTE_LOS':
    if (input === '1' || input === 'sim') {
      nextState = 'MAIN_MENU';
      sessionData = {};
      attempts = 0;
      responseText = '🚨 *Identificamos uma falha no sinal da sua fibra óptica!*\n\nComo a luz LOS está vermelha/piscando, nosso sistema gerou uma notificação para a equipe técnica.\n\n👤 Um de nossos atendentes de suporte entrará em contato em instantes por aqui para agendar a visita técnica!';
    } else if (input === '2' || input === 'nao' || input === 'não') {
      nextState = 'SUPORTE_REBOOT';
      attempts = 0;
      responseText = '🔄 *Reinicialização do Equipamento*\n\nPor favor, retire o seu roteador da tomada, aguarde *30 segundos* e ligue novamente.\n\nApós os LEDs estabilizarem, sua conexão voltou ao normal?\n\n1️⃣ *Sim, normalizou!*\n2️⃣ *Não, continuo sem internet.*';
    } else {
      responseText = handleInvalidInput('Por favor, responda apenas:\n1️⃣ para *Sim*\n2️⃣ para *Não*\n\nA luz *LOS/PON* está *vermelha* ou *piscando*?');
    }
    break;

  case 'SUPORTE_REBOOT':
    if (input === '1' || input === 'sim') {
      nextState = 'MAIN_MENU';
      sessionData = {};
      attempts = 0;
      responseText = '🎉 *Excelente! Ficamos felizes que sua conexão foi restabelecida!*\n\nSe precisar de mais alguma coisa, basta enviar uma nova mensagem. Tenha um ótimo dia! 👋';
    } else if (input === '2' || input === 'nao' || input === 'não') {
      nextState = 'SUPORTE_WIFI_CHECK';
      attempts = 0;
      responseText = '📶 *Verificação de Wi-Fi vs Cabo*\n\nO problema de lentidão/queda está acontecendo *apenas no Wi-Fi* ou também via cabo de rede?\n\n1️⃣ *Apenas no Wi-Fi*\n2️⃣ *Geral (Wi-Fi e Cabo)*';
    } else {
      responseText = handleInvalidInput('Por favor, responda apenas:\n1️⃣ para *Sim (normalizou)*\n2️⃣ para *Não (continua sem internet)*\n\nA sua internet voltou após reiniciar o roteador?');
    }
    break;

  case 'SUPORTE_WIFI_CHECK':
    if (input === '1') {
      nextState = 'MAIN_MENU';
      sessionData = {};
      attempts = 0;
      responseText = '📡 *Encaminhado para Suporte Especializado em Wi-Fi!*\n\nComo o problema é isolado na rede sem fio, transferi seu atendimento para um técnico de suporte analisar os canais e frequência do seu roteador.\n\n👤 Aguarde um momento que um atendente responderá aqui.';
    } else if (input === '2') {
      nextState = 'SUPORTE_DESCRICAO';
      attempts = 0;
      responseText = '📝 *Descreva o problema*\n\nPor favor, envie uma mensagem descrevendo o que está acontecendo (ex: lentidão, sites específicos que não abrem, quedas frequentes):';
    } else {
      responseText = handleInvalidInput('Por favor, responda:\n1️⃣ para *Apenas no Wi-Fi*\n2️⃣ para *Geral (Wi-Fi e Cabo)*');
    }
    break;

  case 'SUPORTE_DESCRICAO':
    nextState = 'MAIN_MENU';
    sessionData = {};
    attempts = 0;
    responseText = '✅ *Informações registradas com sucesso!*\n\nHistórico do diagnóstico:\n• Luz LOS: Normal\n• Reinício do roteador: Não resolveu\n• Tipo da falha: Geral (Wi-Fi e Cabo)\n• Detalhes do cliente: "' + inputData.text + '"\n\n👤 Transferindo para o atendente de suporte com todo esse histórico. Aguarde um momento!';
    break;

  default:
    nextState = 'MAIN_MENU';
    attempts = 0;
    responseText = 'Olá, *' + inputData.pushName + '*! 👋 Seja bem-vindo ao atendimento do seu Provedor de Internet.\n\nPor favor, digite o número da opção desejada:\n\n1️⃣ *Suporte Técnico*\n2️⃣ *Financeiro & 2ª Via*\n3️⃣ *Comercial & Planos*';
    break;
}

const newSessionJson = JSON.stringify({
  state: nextState,
  context: sessionData,
  attempts: attempts,
  updatedAt: new Date().toISOString()
});

return [{
  json: {
    remoteJid: inputData.remoteJid,
    number: inputData.number,
    responseText: responseText,
    newSessionJson: newSessionJson,
    sqlUpsert: `INSERT INTO bot_sessions (remote_jid, session_data, updated_at) VALUES ('${inputData.remoteJid}', '${newSessionJson}', NOW()) ON CONFLICT (remote_jid) DO UPDATE SET session_data = EXCLUDED.session_data, updated_at = NOW();`,
    payload: {
      number: inputData.number,
      text: responseText
    }
  }
}];
